import fs from 'fs';
import { getCachedEnvVars } from './hclUtils.js';
import { getRecursiveDependencies } from './dependencyUtils.js';

const BASE_DIR = '../../mesx-infrastructure';
const pattern = /^r-ca-.*\.tf$/;
const vars = getCachedEnvVars(BASE_DIR, pattern);
//console.log('Loaded environment variables from:', process.env.mesx_infrastructure_DIR );

const prRaw = process.env.prVersion;
const mainRaw = process.env.mainVersion ;


let prVersion, mainVersion;

try {
  prVersion = JSON.parse(prRaw);
  mainVersion = JSON.parse(mainRaw);
} catch (e) {

  console.error('Failed to parse JSON from environment variables:', e.message);
  process.exit(1);
}

function checkForChanges(oldData, newData) {
  const changed = [];

  const allKeys = new Set([...Object.keys(oldData), ...Object.keys(newData)]);
  for (const key of allKeys) {
    const oldVal = oldData[key];
    const newVal = newData[key];


    if (!oldVal || !newVal || JSON.stringify(oldVal) !== JSON.stringify(newVal)) {
      console.log(`Change detected for service: ${key}`);
      console.log(`Old value: ${JSON.stringify(oldVal)}`);    
      console.log(`New value: ${JSON.stringify(newVal)}`);
      changed.push({key, oldVal, newVal});
    }
  }

  return changed;
}

export function compareVersionFiles(mainVersion, prVersion) {
  const changedServices = checkForChanges(mainVersion, prVersion);
const depToCheck = new Set();
  if (changedServices.length > 0) {
    console.log('Detected change in service versions:', changedServices);

    changedServices.forEach(service => {
      console.log(`Service changed: ${service.key}`);
      console.log(`Old value: ${JSON.stringify(service.oldVal)}`);
      console.log(`New value: ${JSON.stringify(service.newVal)}`);
      try {
        const deps = getRecursiveDependencies(service.key, vars);
        console.log(`Dependencies for ${service.key}:`, Array.from(deps));
        for (const dep of deps) {
          depToCheck.add(dep);
        }

      } catch (e) {
        console.error(`Error getting dependencies for ${service}:`, e.message);
      }
    });
  } else {
    console.log('No differences detected between main and PR service versions.');
  }
  return [depToCheck, changedServices];
}

compareVersionFiles(mainVersion, prVersion);

import { normalizeFileName } from './normalizeUtils.js';

export function getDependenciesDescending(fileName, envVarsByFile) {
  if (!fileName || typeof fileName !== 'string') {
    throw new Error('Invalid fileName parameter');
  }
  if (!envVarsByFile || typeof envVarsByFile !== 'object') {
    throw new Error('Invalid envVarsByFile parameter');
  }
  fileName = normalizeFileName(fileName);
  if (!envVarsByFile[fileName]) {
    throw new Error(`File '${fileName}' not found in dependency map.`);
  }
  return envVarsByFile[fileName] || new Set();
}

export function getDependenciesAscending(fileName, envVarsByFile) {
  fileName = normalizeFileName(fileName);
  const dependentFiles = new Set();
  for (const [file, deps] of Object.entries(envVarsByFile)) {
    for (const dep of deps) {
      if (normalizeFileName(dep) === fileName) {
        dependentFiles.add(normalizeFileName(file));
      }
    }
  }
  return dependentFiles;
}

export function getRecursiveDependencies(targetRepoName, envVarsByFile, visited = new Set()) {
  targetRepoName = normalizeFileName(targetRepoName);

  if (!envVarsByFile[targetRepoName]) {
    console.error(`File '${targetRepoName}' not found in dependency map.`);
    process.exit(1);
  }
  if (visited.has(targetRepoName)) return new Set();

  visited.add(targetRepoName);
  const dependencies = getDependenciesAscending(targetRepoName, envVarsByFile);
  const allDeps = new Set(dependencies);
  for (const dep of dependencies) {
    const subDeps = getRecursiveDependencies(dep, envVarsByFile, visited);
    subDeps.forEach(d => {
      allDeps.add(d);
    });
  }
  return allDeps;
}

import fs from 'fs';

export function getFilesMatchingPattern(dir, pattern) {
  return fs.readdirSync(dir).filter(f => pattern.test(f));
}

import { getCachedEnvVars } from './hclUtils.js';
import { getRecursiveDependencies } from './dependencyUtils.js';


import {  TARGET_DIR } from './constants/Urls.js';


export async function handler(req, res) {
  const repoName = req.query.repoName || req.body.repoName;
  if (!repoName) {
    return res.status(400).json({ error: 'Missing repoName parameter' });
  }

  const BASE_DIR = TARGET_DIR;
  const pattern = /^r-ca-.*\.tf$/;
  const vars = getCachedEnvVars(BASE_DIR, pattern);

  if (!vars[repoName]) {

    return res.status(404).json({ error: `Repository '${repoName}' not found in dependency map.` });
  }

  const deps = getRecursiveDependencies(repoName, vars);

  return res.json({
    repoName,
    dependencies: Array.from(deps)
  });
}

import hcltojson from 'hcl-to-json';
import { getFilesMatchingPattern } from './fileUtils.js';
import { normalizeFileName } from './normalizeUtils.js';
import fs from 'fs';
export function cleanJsondecodeExpressions(hclContent) {
  return hclContent.replace(/jsondecode\([^)]*\)/g, '"__IGNORED_EXPRESSION__"');
}

export function findEnv(obj, path = '') {
  if (Array.isArray(obj)) {
    for (let i = 0; i < obj.length; i++) {
      const newPath = `${path}[${i}]`;
      const result = findEnv(obj[i], newPath);
      if (result) return result;
    }
  } else if (typeof obj === 'object' && obj !== null) {
    for (const key in obj) {
      const value = obj[key];
      const newPath = path ? `${path}.${key}` : key;
      if (key === 'env') {
        return { path: newPath, value };
      }
      const result = findEnv(value, newPath);
      if (result) return result;
    }
  }
  return null;
}

export function scanEnvVars(dir, pattern) {
  const files = getFilesMatchingPattern(dir, pattern);
  const envVarsByFile = {};

  files.forEach(file => {
    try {
      const filePath = `${dir}/${file}`;
      const content = fs.readFileSync(filePath, 'utf8');
      const cleanContent = cleanJsondecodeExpressions(content);
      const parsed = hcltojson(cleanContent);
      const envEntry = findEnv(parsed);
      const depList = new Set();

      if (envEntry) {
        const envArray = envEntry.value;
        if (Array.isArray(envArray)) {
          envArray.forEach(item => {
            const name = item.name;
            if (typeof name === 'string' &&(
              name.startsWith('URL_') ||
              name.startsWith('URI_') ||
              name.startsWith('BACKEND_') ||
              name.startsWith('UI_') ||
              name.startsWith('API_') ||
              name.endsWith('_APP_ID') ||
              name.endsWith('_ID') ||
              name.endsWith('_URL') ||
              name.endsWith('_URI'))){
              depList.add(normalizeFileName(name));
            }
          });
        }
      }
      envVarsByFile[normalizeFileName(file)] = depList;
    } catch (err) {
      console.error(`Error processing file ${file}:`, err.message);
    }
  });

  return envVarsByFile;
}

let cachedEnvVars = null;
export function getCachedEnvVars(dir, pattern) {
  if (!cachedEnvVars) {
    cachedEnvVars = scanEnvVars(dir, pattern);
    console.log('Environment variables scanned and cached.');
  } else {
    console.log('Using cached environment variables');
  }
  return cachedEnvVars;
}

export function normalizeFileName(filename) {
  if (!filename) return '';
  let name = filename
    .toLowerCase()
    .replace(/(_?url_?)/gi, '')
    .replace(/-board-/gi, '')
    .replace(/_board_/gi, '')
    .replace(/^r-ca-/, '')
    .replace(/\.tf$/, '')
    .replace(/\.id$/, '')
    .replace(/-/g, '')
    .replace(/_/g, '');
  name = name.replace(/appid$/, '');
  return name;
}

