import https from 'https';
import { compareVersionFiles } from './compareServiceVersions.js';

const organization = process.env.ORG_NAME || 'faurecia-cloud';
const project = process.env.PROJECT_NAME || 'MES_X.0';
const repositoryId = process.env.REPO_ID || 'mesx-proto-dependency-management';
const pullRequestId =  process.env.PR_ID;
const personalAccessToken = process.env.SYSTEM_ACCESSTOKEN;

const prRaw = process.env.prVersion;
const mainRaw = process.env.mainVersion ;



let prVersion, mainVersion;

try {
  prVersion = JSON.parse(prRaw);
  mainVersion = JSON.parse(mainRaw);
} catch (e) {

  console.error('Failed to parse JSON from environment variables:', e.message);
  process.exit(1);
}
if (!repositoryId || !pullRequestId || !personalAccessToken) {
  console.error('❌ Missing required environment variables');
  process.exit(1);
}
const [changedDependencies,changedServices] = compareVersionFiles(mainVersion, prVersion);

const auth = Buffer.from(`:${personalAccessToken}`).toString('base64');

const postData = JSON.stringify({
  comments: [
    {
      parentCommentId: 0,
      content: `📦 Service Version Updates

| Service | Old Version | New Version |
|---------|-------------|-------------|
${changedServices.map(service => `| \`${service.key}\` | \`${JSON.stringify(service.oldVal)}\` | \`${JSON.stringify(service.newVal)}\` |`).join('\n')}

---

### 🔁 Potentially Affected Dependencies
${Array.from(changedDependencies).map(dep => `- \`${dep}\``).join('\n')}

> ⚠️ Please ensure compatibility before merging. ✅
`,
      commentType: 1
    }
  ],
  status: 'active'
});

const options = {
  hostname: 'dev.azure.com',
  path: `/${organization}/${encodeURIComponent(project)}/_apis/git/repositories/${repositoryId}/pullRequests/${pullRequestId}/threads?api-version=7.0`,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
    'Authorization': `Basic ${auth}`
  }
};

const req = https.request(options, (res) => {
  let data = '';

  res.on('data', chunk => {
    data += chunk;
  });

  res.on('end', () => {
    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('✅ Comment created successfully');
      console.log(JSON.parse(data));
    } else {
      console.error(`❌ Failed with status ${res.statusCode}`);
      console.error(data);
    }
  });
});

req.on('error', (e) => {
  console.error(`❌ Request error: ${e.message}`);
});

req.write(postData);
req.end();
